        # Detect marker at left or right edge
        left_edge_marker = row[0] != background
        right_edge_marker = row[-1] != background

        # Find scattered markers (non-background)
        scattered = [(c, v) for c, v in enumerate(row) if v != background and c > 0 and c < len(row) - 1]

        if scattered:
            scattered.sort()
            for scatter_col, _ in scattered:
                cells_after_scatter = len(row) - scatter_col - 1
                cells_before_scatter = scatter_col - 1

                # Left edge marker present: fill from 1 to scatter_col, set scatter_col+1 to 4 (or scatter_col)
                if left_edge_marker:
                    if cells_after_scatter > 8:
                        # Fill 1 to scatter_col, set scatter_col+1 to 4
                        for c in range(1, scatter_col + 1):
